            "id": "w1",
            "statement": "Skyworks와의 약 $22B 합병이 주가·내부자 공시 해석의 핵심으로 보도됨. 상승 1M 22.77%가 딜 프리미엄 반영인지는 조건(대가·클로징 일정)을 본 자료에서 확인하지 못해 단정 불가.",
